package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.complex.Complex#add(Complex rhs)
 */
public class Complex_add_TriageGen3Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testAdd_PositiveNumbers() throws NullArgumentException {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(3.0, 4.0);
        Complex expected = new Complex(4.0, 6.0);
        Complex result = c1.add(c2);

        Assert.assertEquals("Real part should be 4.0", expected.getReal(), result.getReal(), DELTA);
        Assert.assertEquals("Imaginary part should be 6.0", expected.getImaginary(), result.getImaginary(), DELTA);
    }

    @Test
    public void testAdd_NegativeNumbers() throws NullArgumentException {
        Complex c1 = new Complex(-1.5, -2.5);
        Complex c2 = new Complex(-3.5, -4.5);
        Complex expected = new Complex(-5.0, -7.0);
        Complex result = c1.add(c2);

        Assert.assertEquals("Real part should be -5.0", expected.getReal(), result.getReal(), DELTA);
        Assert.assertEquals("Imaginary part should be -7.0", expected.getImaginary(), result.getImaginary(), DELTA);
    }

    @Test
    public void testAdd_MixedNumbers() throws NullArgumentException {
        Complex c1 = new Complex(5.0, -2.0);
        Complex c2 = new Complex(-3.0, 4.0);
        Complex expected = new Complex(2.0, 2.0);
        Complex result = c1.add(c2);

        Assert.assertEquals("Real part should be 2.0", expected.getReal(), result.getReal(), DELTA);
        Assert.assertEquals("Imaginary part should be 2.0", expected.getImaginary(), result.getImaginary(), DELTA);
    }

    @Test
    public void testAdd_Zero() throws NullArgumentException {
        Complex c1 = new Complex(10.0, 10.0);
        Complex c2 = new Complex(0.0, 0.0);
        Complex expected = new Complex(10.0, 10.0);
        Complex result = c1.add(c2);

        Assert.assertEquals("Real part should be unchanged", expected.getReal(), result.getReal(), DELTA);
        Assert.assertEquals("Imaginary part should be unchanged", expected.getImaginary(), result.getImaginary(), DELTA);
    }

    @Test
    public void testAdd_Infinity() throws NullArgumentException {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.add(c2);

        Assert.assertTrue("Real part should be infinity", Double.isInfinite(result.getReal()));
        Assert.assertEquals("Imaginary part should be 2.0", 2.0, result.getImaginary(), DELTA);
    }

    @Test(expected = NullArgumentException.class)
    public void testAdd_NullArgument() throws NullArgumentException {
        Complex c1 = new Complex(1.0, 1.0);
        c1.add(null);
    }

    @Test
    public void testAdd_NaN() throws NullArgumentException {
        Complex c1 = new Complex(Double.NaN, 1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.add(c2);

        Assert.assertTrue("Real part should be NaN", Double.isNaN(result.getReal()));
        Assert.assertEquals("Imaginary part should be 2.0", 2.0, result.getImaginary(), DELTA);
    }
}
